def run_pipeline(batch):
    enforce_contract(batch)            # contract at the source
    validate(batch)                    # gate on rules
    load(batch)
    metrics = observe(batch)           # five pillars
    for m in metrics:
        if m.is_anomalous():
            incident = open_incident(m)
            incident.attach(trace_lineage(m.dataset))
            route_alert(incident)      # SLO-driven response
